-- Default grants for tables created above, plus anything added later.
grant select on all tables in schema knowledge to anon, authenticated;
alter default privileges in schema knowledge
  grant select on tables to anon, authenticated;

-- Sync bookkeeping. One row per run, so an operator can answer "what happened on
-- the 14th" from SQL rather than from a log file on whichever machine ran it.
create table if not exists knowledge.sync_runs (
  run_id            text primary key,
  mode              text not null,
  outcome           text not null,
  version           text,
  started_at        timestamptz not null,
  finished_at       timestamptz,
  duration_seconds  numeric,
  rows_inserted     integer not null default 0,
  rows_updated      integer not null default 0,
  rows_deleted      integer not null default 0,
  rows_skipped      integer not null default 0,
  validation_errors integer not null default 0,
  metrics           jsonb not null default '{}'::jsonb
);
create index if not exists sync_runs_started_idx
  on knowledge.sync_runs (started_at desc);

alter table knowledge.sync_runs enable row level security;
drop policy if exists "sync runs admin read" on knowledge.sync_runs;
create policy "sync runs admin read"
  on knowledge.sync_runs for select
  using (public.is_valueweave_admin());

